export type ContactInput = { name: string; email: string; company: string; service: string; budget: string; message: string };
export type Errors = Partial<Record<keyof ContactInput, string>>;

export function validate(v: ContactInput): Errors {
  const e: Errors = {};
  if (v.name.trim().length < 2) e.name = "Please enter your name.";
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.email.trim())) e.email = "Please enter a valid email address.";
  if (!v.service) e.service = "Please choose a service.";
  if (!v.budget) e.budget = "Please choose a budget range.";
  if (v.message.trim().length < 20) e.message = "Please describe your project in at least 20 characters.";
  if (v.message.length > 4000) e.message = "Please keep the description under 4000 characters.";
  return e;
}
